if ~exist('src200sym','var')
    src200sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei200_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src200sym,line_proj('offset',[0,0,1]),0.02,0.02,[-0.1,0.1],[95,105]);
plot(w2_000a);lz 0 1;keep_figure; %[output:0312f1d4]
w2_000b = cut(src200sym,line_proj(),0.02,0.02,[-0.1,0.1],[45,55]);
plot(w2_000b);lz 0 1; keep_figure; %[output:23111913]

hc.log_level = ll;

allCutPar200 = {[-0.1,0.1],[-0.1,0.1],[0,2,160]};
file = src200.full_filename %[output:61d2b0b7]
[~,fname200] = fileparts(file);

%%
w4 = cut(src200sym,line_proj([1,0,0],[0,1,0],'offset',[1,1,0]), ... %[output:group:31ace1b6] %[output:120524be] %[output:48a6a040]
    [-0.5,0.005,0.5],[-0.5,0.02,0.5],[-0.5,0.02,0.5],[-10,2,130]) %[output:group:31ace1b6] %[output:120524be] %[output:48a6a040]
%%

w2h = cut(w4, 0.005,[-0.05,0.05],[-0.05,0.05],[]); %[output:28b30212]
plot(w2h);lz 0 1; keep_figure; %[output:4180c4a2]

w2k = cut(w4,[-0.05,0.05], 0.005,[-0.05,0.05],[]); %[output:25e2c111]
plot(w2k);lz 0 1; keep_figure; %[output:897636d5]

w2l = cut(w4,[-0.05,0.05],[-0.05,0.05], 0.005,[]); %[output:1c2a2370]
plot(w2l);lz 0 1; keep_figure; %[output:566c7f37]

%%
w4fit = cut(w4,[],[],[],[45,2,110]); %[output:365ddb70]
%%
hc.log_level = -2;
ei = 50 %[output:10ddbda7]
w2bg = cut(w4,sphere_proj('offset',[1,1,0]),[0,1],[0,2,180],[-180,2,180],[ei-5,ei+5]);
plot(w2bg); keep_figure; %[output:3b7837f4]
%%

ei = 20;
w1 = cut(w4,sphere_proj('offset',[1,1,0]),[],[0,180],[-180,180],[ei-5,ei+5]);
acolor k;
plot(w1);  %[output:235f15d4]
ei = 50;
w1 = cut(w4,sphere_proj('offset',[1,1,0]),[],[0,180],[-180,180],[ei-5,ei+5]);
acolor g;
pd(w1); %[output:235f15d4]
ei = 120;
w1lrg = cut(w4,sphere_proj('offset',[1,1,0]),[],[0,180],[-180,180],[ei-5,ei+5]);
acolor b
pd(w1rg); keep_figure %[output:235f15d4]
%%
w1lrg = cut(w4,sphere_proj('offset',[1,1,0]),[0.55,1],[0,180],[-180,180],[45,2,120]);
w1sml = cut(w4,sphere_proj('offset',[1,1,0]),[0,0.1],[0,180],[-180,180],[45,2,120]);
acolor k; pd(w1lrg); %[output:24784c13]
acolor g; pd(w1sml); liny; keep_figure %[output:24784c13]
%%

w2 = cut(w4,sphere_proj('offset',[1,1,0]),[0.0,0.01,1],[0,180],[-180,180],[45,2,120]);
plot(w2); %[output:1ad24852]
%%

ei = 50;
w2bg = cut(w4,sphere_proj('offset',[1,1,0]),[0.4,1],[0,1,180],[-180,2,180],[ei-5,ei+5]); %[output:7f9a4a18]
plot(w2bg); keep_figure;
%%
gamma=10;gm1=0;gm2=0;
Seff0=0.7917;

J0=39;
correct_ff = 1;
gap = 0;    %
ff_corr = 0; % corrections to magnetic form factor
init_fg_param = [correct_ff,8,gamma,gm1,gm2,Seff0,  0,   J0, ff_corr];

kk = tobyfit(spp.Ei800_off200GHmaxNbg);
kk = kk.set_fun(@sqw_iron_gpar);
hkl_proj = spp.Ei800_off200GHmaxNbg.data.proj;

%init_fg_params = [coffect_ff,T,gamma,gm1,gm2,Seff, gap, J0, ff_corr];
free_sw_param  =  [0          0, 1   ,1   1,   1,    0,   1, 1,];

kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);


%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);


[fit_obj,fit_par] = kk.fit();

